-- Подсадка — в открытую версию: пункт судит только её (решение владельца 2026-10-07).
INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin, parent_task_id) SELECT $1,'M9-TPROBE', м.id, 9999, 'подсадка самотеста', 'S', 'not_started', 'red', 'declared', '' FROM (SELECT (SELECT m.id FROM project_plan_milestones m JOIN version_scope s ON s.project_id = m.project_id AND s.version = m.version_id WHERE m.project_id = $1 ORDER BY CASE coalesce(s.scope, 'open') WHEN 'open' THEN 0 WHEN 'closed' THEN 1 ELSE 2 END, m.id LIMIT 1) AS id) м WHERE м.id IS NOT NULL
